using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed discriminator property from
            // "Discriminator" to "$type". Existing documents use "Discriminator".
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF 9 changed the id format from
            // "EntityType|Key" (e.g. "Blog|1") to just the key value.
            // Opt back into the legacy format for existing documents.
            entity.HasIdProperty(b => b.Id);
            entity.Property("__id")
                .ToJsonProperty("id")
                .ValueGeneratedOnAdd();

            // Breaking change 3: EF 9 throws for HasIndex on Cosmos
            // (previously silently ignored). The HasIndex call is removed.

            // Breaking change 4 (noted in SyncJob.cs): SaveChanges now uses
            // patch (partial update) instead of full-document replace.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

