using System.Linq;

class SyncJob
{
    // Breaking change 4: EF 9 Cosmos provider uses patch-based (partial) updates
    // by default instead of full-document replace. This is generally fine but
    // behavior differs if you rely on removing unset properties from documents.
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

