 using Microsoft.EntityFrameworkCore;

 class BlogContext : DbContext
 {
     public DbSet<Blog> Blogs => Set<Blog>();

     protected override void OnModelCreating(ModelBuilder modelBuilder)
     {
         modelBuilder.Entity<Blog>(entity =>
         {
             // Breaking change 1: EF 9 renamed the discriminator JSON property
             // from "Discriminator" to "$type". Existing documents still store
             // "Discriminator", so configure the property to use the old name.
             entity.HasDiscriminator<string>("Discriminator");
             entity.Property("Discriminator").ToJsonProperty("Discriminator");

             // Breaking change 2: EF 9 no longer prepends the discriminator to
             // the JSON "id" value (old format: "Blog|1", new: "1"). Opt back in
             // so existing documents with "Blog|1" ids can still be read.
             entity.HasDiscriminatorInJsonId();

             // Breaking change 3: HasIndex now throws on the Cosmos provider
             // (previously it was silently ignored). The HasIndex call is removed.

             // Breaking change 4 (see SyncJob.cs): SaveChanges now uses
             // patch-based partial updates instead of full-document replace.
         });
     }
 }

 class Blog
 {
     public string Id { get; set; }
     public string Name { get; set; }
 }

